          "after": "import OpenAI from \"openai\";\nimport { input } from \"@inquirer/prompts\";\nimport { type ChatCompletionMessageParam } from \"openai/resources\";\n\nconst client = new OpenAI({\n  baseURL: process.env.LLAMA_BASE_URL || \"http://127.0.0.1:8888/v1\",\n  apiKey: process.env.LLAMA_API_KEY || \"local\",\n  maxRetries: 0,\n  timeout: 120_000,\n});\n\nconsole.log(\"Local assistant — type end to finish.\");\n\nlet currentMessage = {\n  role: \"user\" as const,\n  content: await input({ message: \"You: \" }),\n};\nconst messages: ChatCompletionMessageParam[] = [];\n\nwhile (currentMessage.content !== \"end\") {\n  messages.push(currentMessage);\n  const completions = await client.chat.completions.create({\n    messages,\n    model: \"GEMMA\",\n  });\n  const answer = completions.choices[0].message.content;\n\n  console.log(answer);\n  messages.push({ role: \"assistant\", content: answer ?? \"\" });\n\n  currentMessage = {\n    role: \"user\" as const,\n    content: await input({ message: \"You: \" }),\n  };\n}\n",
